    });

    // 9a. Concrete Plinth Foundation
    const plinth = new THREE.Mesh(new THREE.CylinderGeometry(2.72, 2.95, 1.2, 8), whiteConcreteMat);
    plinth.position.y = 0.2;
    plinth.castShadow = true;
