    // 9b. Tapered Octagonal Tower Shaft
    const towerHeight = 10.6;
    const towerGeo = new THREE.CylinderGeometry(1.56, 2.48, towerHeight, 8);
    const towerMesh = new THREE.Mesh(towerGeo, whiteConcreteMat);
    towerMesh.position.y = 0.75 + towerHeight * 0.5;
    towerMesh.castShadow = true;
    towerMesh.receiveShadow = true;
