    const porchDoor = new THREE.Mesh(new THREE.BoxGeometry(0.68, 1.85, 0.1), whiteConcreteMat);
    porchDoor.position.set(0.32, -0.35, 0.71);
    porchGroup.add(porchDoor);
    const doorFrame = new THREE.Mesh(new THREE.BoxGeometry(0.76, 1.92, 0.06), new THREE.MeshStandardMaterial({ color: 0xd0d7e0, roughness: 0.7 }));
    doorFrame.position.set(0.32, -0.35, 0.70);
    porchGroup.add(doorFrame);
    const porchSmallVent = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.24, 0.08), darkRecessMat);
    porchSmallVent.position.set(-0.35, 0.35, 0.72);
    porchGroup.add(porchSmallVent);
    lighthouseGroup.add(porchGroup);

    // 9d. Tower Windows & Lower Dark Vent (matching right-front & right faces in photo)
    const lowerWindow = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.48, 0.18), darkRecessMat);
    lowerWindow.position.set(0.62, 2.25, 2.18);
    lowerWindow.rotation.y = 0.26;
    lighthouseGroup.add(lowerWindow);

    const slitYPositions = [5.1, 7.6, 9.6];
    for (let i = 0; i < slitYPositions.length; i++) {
      const y = slitYPositions[i];
      const rAtY = THREE.MathUtils.lerp(2.48, 1.56, (y - 0.75) / towerHeight) * 0.92;
      const slit = new THREE.Mesh(new THREE.BoxGeometry(0.20, 0.88, 0.22), darkRecessMat);
      const angle = i === 2 ? 0.95 : 1.05;
      slit.position.set(Math.sin(angle) * rAtY, y, Math.cos(angle) * rAtY);
      slit.rotation.y = angle;
      lighthouseGroup.add(slit);
    }

    // 9e. Corbelled Flared Gallery Deck
    const galleryBaseY = 0.75 + towerHeight;
    const flare = new THREE.Mesh(new THREE.CylinderGeometry(2.14, 1.58, 0.62, 8), whiteConcreteMat);
    flare.position.y = galleryBaseY + 0.31;
    flare.castShadow = true;
    flare.receiveShadow = true;
    lighthouseGroup.add(flare);

    const deckSlab = new THREE.Mesh(new THREE.CylinderGeometry(2.18, 2.14, 0.22, 8), whiteConcreteMat);
    deckSlab.position.y = galleryBaseY + 0.72;
    deckSlab.castShadow = true;
    deckSlab.receiveShadow = true;
    lighthouseGroup.add(deckSlab);

    // Gallery Railing (8 posts + 2 horizontal octagonal rail loops)
    const railY = galleryBaseY + 0.83;
    const railR = 2.04;
    const railH = 0.96;
    const railPts = [];
    for (let i = 0; i < 8; i++) {
      const ang = (i / 8) * Math.PI * 2 + Math.PI / 8;
      const px = Math.cos(ang) * railR;
      const pz = Math.sin(ang) * railR;
