        const segLen = p1.distanceTo(p2);
        const railBar = new THREE.Mesh(new THREE.CylinderGeometry(0.026, 0.026, segLen, 8), whiteMetalMat);
        railBar.position.set((p1.x + p2.x) * 0.5, railY + hOff, (p1.z + p2.z) * 0.5);
        railBar.quaternion.setFromUnitVectors(
          new THREE.Vector3(0, 1, 0),
          new THREE.Vector3(p2.x - p1.x, 0, p2.z - p1.z).normalize()
