    // 9f. Red Lantern Room Base (Parapet)
    const lanternBaseY = galleryBaseY + 0.83;
    const redParapet = new THREE.Mesh(new THREE.CylinderGeometry(1.36, 1.38, 1.05, 8), redMetalMat);
