    // 9g. Lantern Glazing + Mullions + Internal Fresnel Lens
    const glassY = lanternBaseY + 1.09;
    const glassH = 1.28;
    const glassCylinder = new THREE.Mesh(new THREE.CylinderGeometry(1.30, 1.30, glassH, 8), lanternGlassMat);
    glassCylinder.position.y = glassY + glassH * 0.5;
    lighthouseGroup.add(glassCylinder);

    // 8 Vertical red mullions around lantern glass
    for (let i = 0; i < 8; i++) {
      const ang = (i / 8) * Math.PI * 2 + Math.PI / 8;
      const mullion = new THREE.Mesh(new THREE.CylinderGeometry(0.036, 0.036, glassH + 0.06, 6), redMetalMat);
      mullion.position.set(Math.cos(ang) * 1.32, glassY + glassH * 0.5, Math.sin(ang) * 1.32);
      lighthouseGroup.add(mullion);
    }

    // Internal Fresnel Lens & Lamp Core
    const lensY = glassY + glassH * 0.52;
    const brassMat = new THREE.MeshStandardMaterial({ color: 0xb08a3e, roughness: 0.3, metalness: 0.85 });
    const lensPedestal = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.42, 0.55, 12), brassMat);
    lensPedestal.position.y = glassY + 0.25;
    lighthouseGroup.add(lensPedestal);

    const lampCoreMat = new THREE.MeshStandardMaterial({
      color: 0xfff5d6,
      emissive: new THREE.Color(0xffcf70),
      emissiveIntensity: 0.45,
      roughness: 0.15
    });
    const fresnelCore = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.42, 0.68, 16), lampCoreMat);
    fresnelCore.position.y = lensY;
    lighthouseGroup.add(fresnelCore);

    // Optional Rotating Volumetric Lighthouse Beam (toggled via UI or Blue Hour)
    const beamPivot = new THREE.Group();
    beamPivot.position.y = lensY;
    beamPivot.visible = false;
    lighthouseGroup.add(beamPivot);

    const beamMat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      uniforms: {
        uColor: { value: new THREE.Color(0xffdfa0) },
        uOpacity: { value: 0.28 }
      },
      vertexShader: `
        varying vec2 vUv;
        varying vec3 vNorm;
        varying vec3 vView;
        void main() {
          vUv = uv;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          vNorm = normalize(normalMatrix * normal);
          vView = normalize(-mv.xyz);
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        varying vec2 vUv;
        varying vec3 vNorm;
        varying vec3 vView;
        uniform vec3 uColor;
        uniform float uOpacity;
        void main() {
          float edge = pow(abs(dot(vNorm, vView)), 1.6);
          float fade = smoothstep(0.0, 0.12, vUv.y) * pow(1.0 - vUv.y, 1.85);
          gl_FragColor = vec4(uColor, edge * fade * uOpacity);
        }
      `
    });
    const beamLen = 56;
    const beamConeGeo = new THREE.ConeGeometry(7.2, beamLen, 28, 1, true);
    beamConeGeo.translate(0, -beamLen * 0.5, 0);
    beamConeGeo.rotateX(Math.PI / 2);

    const beamA = new THREE.Mesh(beamConeGeo, beamMat);
    beamA.position.z = 0.5;
    beamPivot.add(beamA);
    const beamB = new THREE.Mesh(beamConeGeo, beamMat);
    beamB.rotation.y = Math.PI;
    beamB.position.z = -0.5;
    beamPivot.add(beamB);

    const beaconPointLight = new THREE.PointLight(0xffcf78, 0, 28);
    beaconPointLight.position.y = lensY;
    lighthouseGroup.add(beaconPointLight);

    // 9h. Red Conical Octagonal Roof + Standing Seams + Ventilator Ball Finial
    const roofBaseY = glassY + glassH;
    const roofEave = new THREE.Mesh(new THREE.CylinderGeometry(1.52, 1.48, 0.16, 8), redMetalMat);
    roofEave.position.y = roofBaseY + 0.08;
    roofEave.castShadow = true;
    lighthouseGroup.add(roofEave);

    const roofCone = new THREE.Mesh(new THREE.ConeGeometry(1.48, 1.28, 8), redMetalMat);
    roofCone.position.y = roofBaseY + 0.16 + 0.64;
    roofCone.castShadow = true;
    lighthouseGroup.add(roofCone);

    const ventCap = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.28, 0.34, 12), redMetalMat);
    ventCap.position.y = roofBaseY + 1.42;
    lighthouseGroup.add(ventCap);

    const finialBall = new THREE.Mesh(new THREE.SphereGeometry(0.20, 14, 12), redMetalMat);
    finialBall.position.y = roofBaseY + 1.68;
    lighthouseGroup.add(finialBall);

    const lightningRod = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.022, 0.55, 6), redMetalMat);
    lightningRod.position.y = roofBaseY + 2.02;
    lighthouseGroup.add(lightningRod);

    // 9i. Small Dark Iron Handrail on the Granite Steps (right of lighthouse base, visible in photo)
    const ironMat = new THREE.MeshStandardMaterial({ color: 0x22262c, roughness: 0.55, metalness: 0.7 });
    const stairRailGroup = new THREE.Group();
    stairRailGroup.position.set(2.95, 0.65, 0.75);
    for (const dx of [0, 1.35]) {
      const p = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 1.05, 6), ironMat);
      p.position.set(dx, 0.5 - dx * 0.28, 0);
      stairRailGroup.add(p);
    }
    const topRail = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 1.5, 6), ironMat);
    topRail.position.set(0.68, 0.82, 0);
    topRail.rotation.z = Math.PI / 2 - 0.27;
    stairRailGroup.add(topRail);
    lighthouseGroup.add(stairRailGroup);

    // =========================================================================
    // 10. DRY WINTER COASTAL GRASS TUFTS (Instanced in rocky crevices)
    // =========================================================================
    const grassCount = 950;
    const bladeGeo = new THREE.ConeGeometry(0.035, 0.42, 3);
    bladeGeo.translate(0, 0.21, 0);
    const grassMat = new THREE.MeshStandardMaterial({
      color: 0x867458,
      roughness: 0.92,
      metalness: 0.0
    });
    const grassInst = new THREE.InstancedMesh(bladeGeo, grassMat, grassCount);
    const dummy = new THREE.Object3D();
    const gColor = new THREE.Color();
    let placed = 0;

    for (let i = 0; i < 4500 && placed < grassCount; i++) {
      const gx = (hash2(i * 1.13, 4.7) - 0.5) * 44.0;
      const gz = (hash2(i * 2.31, 9.2) - 0.5) * 52.0 + 4.0;
      const gy = getTerrainHeight(gx, gz);
      if (gy < 2.2) continue;
      // Avoid lighthouse footprint & icy path center
      if (Math.hypot(gx - LIGHTHOUSE_POS.x, gz - LIGHTHOUSE_POS.z) < 4.5) continue;
      if (Math.abs(gx - getPathCenterX(gz)) < 1.35) continue;

      // Cluster into natural coastal tussocks
      const cluster = fbm2D(gx * 0.35 + 12.0, gz * 0.35 - 5.0, 2);
      if (cluster < 0.57) continue;

      const s = 0.55 + hash2(i, 7.7) * 0.9;
      dummy.position.set(gx, gy - 0.04, gz);
      dummy.rotation.set(
        (hash2(i, 1.1) - 0.5) * 0.65,
        hash2(i, 2.2) * Math.PI * 2,
        (hash2(i, 3.3) - 0.5) * 0.65
      );
      dummy.scale.set(s, s * (0.75 + hash2(i, 5.5) * 0.6), s);
      dummy.updateMatrix();
      grassInst.setMatrixAt(placed, dummy.matrix);

      gColor.setHSL(0.09 + (hash2(i, 8.8) - 0.5) * 0.03, 0.24, 0.34 + hash2(i, 6.6) * 0.14);
      grassInst.setColorAt(placed, gColor);
      placed++;
    }
    grassInst.count = placed;
    grassInst.instanceMatrix.needsUpdate = true;
    if (grassInst.instanceColor) grassInst.instanceColor.needsUpdate = true;
    scene.add(grassInst);

    // =========================================================================
    // 11. ANIMATED COLD ATLANTIC OCEAN SHADER (Waves, Fresnel, Surf Foam)
    // =========================================================================
    const oceanUniforms = {
      uTime: { value: 0 },
      uSunDir: { value: skyUniforms.uSunDir.value },
      uSunColor: { value: new THREE.Color(0xfff5e4) },
      uSkyHorizon: { value: skyUniforms.uHorizonColor.value },
      uSkyZenith: { value: skyUniforms.uZenithColor.value },
      uDeepColor: { value: new THREE.Color(0x0d2d4a) },
      uShallowColor: { value: new THREE.Color(0x1f5378) }
    };

    const oceanGeo = new THREE.PlaneGeometry(1600, 1600, 140, 140);
    oceanGeo.rotateX(-Math.PI / 2);

    const oceanMat = new THREE.ShaderMaterial({
      uniforms: oceanUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec3 vWorldPos;
        varying float vWaveH;
        void main() {
          vec4 wp = modelMatrix * vec4(position, 1.0);
          float d = length(wp.xz);
          float atten = 1.0 - smoothstep(140.0, 620.0, d);
          float w1 = sin(wp.x * 0.16 + wp.z * 0.12 + uTime * 1.15) * 0.16;
          float w2 = sin(wp.x * -0.09 + wp.z * 0.21 + uTime * 1.45) * 0.11;
          float w3 = cos(wp.x * 0.28 - wp.z * 0.17 + uTime * 1.85) * 0.05;
          float h = (w1 + w2 + w3) * atten;
          wp.y += h;
          vWaveH = h;
          vWorldPos = wp.xyz;
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uSunDir;
        uniform vec3 uSunColor;
        uniform vec3 uSkyHorizon;
        uniform vec3 uSkyZenith;
        uniform vec3 uDeepColor;
        uniform vec3 uShallowColor;

        varying vec3 vWorldPos;
        varying float vWaveH;

        float hash(vec2 p) {
          return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
        }
        float noise(vec2 p) {
          vec2 i = floor(p);
          vec2 f = fract(p);
          vec2 u = f * f * (3.0 - 2.0 * f);
          return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
                     mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
        }
        float waveHeight(vec2 p) {
          float t = uTime;
          float h = 0.0;
          h += noise(p * 0.22 + vec2(t * 0.35, t * 0.22)) * 0.55;
          h += noise(p * 0.58 - vec2(t * 0.45, -t * 0.31)) * 0.28;
          h += noise(p * 1.45 + vec2(-t * 0.62, t * 0.54)) * 0.12;
          h += noise(p * 3.20 + vec2(t * 0.85, -t * 0.7)) * 0.05;
          return h;
        }

        void main() {
          vec3 viewVec = cameraPosition - vWorldPos;
          float dist = length(viewVec);
          vec3 V = viewVec / dist;

          // Finite-difference micro-wave normal (fades slightly with distance to avoid aliasing)
          float eps = mix(0.18, 1.2, smoothstep(20.0, 350.0, dist));
          float hC = waveHeight(vWorldPos.xz);
          float hX = waveHeight(vWorldPos.xz + vec2(eps, 0.0));
          float hZ = waveHeight(vWorldPos.xz + vec2(0.0, eps));
          float bumpScale = mix(0.65, 0.22, smoothstep(40.0, 420.0, dist));
          vec3 N = normalize(vec3((hC - hX) * bumpScale / eps, 1.0, (hC - hZ) * bumpScale / eps));

          // Physically inspired Fresnel reflection
          float NdotV = max(dot(N, V), 0.001);
          float fresnel = 0.03 + 0.97 * pow(1.0 - NdotV, 4.6);

          vec3 R = reflect(-V, N);
          vec3 skyRefl = mix(uSkyHorizon, uSkyZenith, pow(clamp(R.y, 0.0, 1.0), 0.55));

          vec3 waterBase = mix(uDeepColor, uShallowColor, clamp(hC * 0.85 + 0.15, 0.0, 1.0));
          vec3 col = mix(waterBase, skyRefl, clamp(fresnel * 0.92, 0.0, 0.88));

          // Crisp winter sun specular glints on choppy swells
          vec3 L = normalize(uSunDir);
          vec3 H = normalize(L + V);
          float specTight = pow(max(dot(N, H), 0.0), 260.0) * 2.2;
          float specBroad = pow(max(dot(N, H), 0.0), 26.0) * 0.18;
          col += uSunColor * (specTight + specBroad);

          // Shoreline surf foam ring around the granite headland
          vec2 penUV = vec2((vWorldPos.x - 1.2) / 30.0, (vWorldPos.z + 2.0) / 44.0);
          float penDist = length(penUV);
          float shoreBand = smoothstep(1.38, 1.02, penDist) * smoothstep(0.76, 1.08, penDist);
          float surfWave = sin(penDist * 28.0 - uTime * 2.2 + hC * 4.5) * 0.5 + 0.5;
          float foam = shoreBand * smoothstep(0.42, 0.82, surfWave * 0.65 + hC * 0.55) * 0.72;
          col = mix(col, vec3(0.86, 0.92, 0.97), foam);

          // Atmospheric distance haze blending cleanly to the horizon
          float fogFactor = 1.0 - exp(-pow(dist * 0.00155, 1.6));
          col = mix(col, uSkyHorizon, clamp(fogFactor, 0.0, 1.0));

          gl_FragColor = vec4(col, 1.0);
        }
      `
    });
    const oceanMesh = new THREE.Mesh(oceanGeo, oceanMat);
    oceanMesh.position.y = 0.0;
    scene.add(oceanMesh);

    // =========================================================================
    // 12. DISTANT COASTLINE HILLS (St. Margaret's Bay right + island sliver left)
    // =========================================================================
    function createDistantLand(startAngle, endAngle, radius, maxHeight, seed) {
      const segs = 90;
      const geo = new THREE.BufferGeometry();
      const verts = [];
      const indices = [];

      for (let i = 0; i <= segs; i++) {
        const t = i / segs;
        const ang = THREE.MathUtils.lerp(startAngle, endAngle, t);
        const envelope = Math.sin(t * Math.PI);
        const h = (0.35 + 0.65 * fbm2D(t * 7.5 + seed, seed, 4)) * maxHeight * Math.pow(envelope, 0.65);

        const x = Math.sin(ang) * radius;
        const z = -Math.cos(ang) * radius;
        verts.push(x, -1.5, z);
        verts.push(x, h, z);
      }
      for (let i = 0; i < segs; i++) {
        const a = i * 2, b = a + 1, c = a + 2, d = a + 3;
        indices.push(a, b, c, b, d, c);
      }
      geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
      geo.setIndex(indices);
      geo.computeVertexNormals();

      const mat = new THREE.MeshStandardMaterial({
        color: 0x455a73,
        roughness: 0.95,
        metalness: 0.0,
        side: THREE.DoubleSide
      });
      return new THREE.Mesh(geo, mat);
    }

    // Right horizon hills (St. Margaret's Bay coastline matching the photo)
    const rightCoast = createDistantLand(0.14, 1.35, 560, 17.5, 3.2);
    scene.add(rightCoast);

    // Tiny low island sliver on the left horizon (matching the photo)
    const leftIsland = createDistantLand(-0.56, -0.34, 580, 4.2, 8.7);
    scene.add(leftIsland);

    // =========================================================================
    // 13. OPTIONAL LIGHT SNOW FLURRIES (Particle System)
    // =========================================================================
    const snowCount = 1400;
    const snowGeo = new THREE.BufferGeometry();
    const snowPositions = new Float32Array(snowCount * 3);
    const snowSeeds = new Float32Array(snowCount);
    for (let i = 0; i < snowCount; i++) {
      snowPositions[i * 3]     = (Math.random() - 0.5) * 90;
      snowPositions[i * 3 + 1] = Math.random() * 34 + 1;
      snowPositions[i * 3 + 2] = (Math.random() - 0.5) * 90;
      snowSeeds[i] = Math.random() * Math.PI * 2;
    }
    snowGeo.setAttribute('position', new THREE.BufferAttribute(snowPositions, 3));
    const snowMat = new THREE.PointsMaterial({
      color: 0xffffff,
      size: 0.16,
      transparent: true,
      opacity: 0.78,
      depthWrite: false
    });
    const snowPoints = new THREE.Points(snowGeo, snowMat);
    snowPoints.visible = false;
    scene.add(snowPoints);

    // =========================================================================
    // 14. LIGHTING PRESETS (Winter Sun / Sunset / Blue Hour)
    // =========================================================================
    const LIGHT_PRESETS = {
      noon: {
        sunDir: new THREE.Vector3(-0.76, 0.44, 0.47).normalize(),
        sunColor: 0xfff7ec,
        sunIntensity: 3.15,
        hemiSky: 0x7eb4f2,
        hemiGround: 0x8ea4bc,
        hemiIntensity: 0.94,
        zenith: 0x356fc2,
        midSky: 0x6ea0de,
        horizon: 0xcce0f5,
        cloudTint: 0xdde8f5,
        fogColor: 0xc5dbf0,
        exposure: 1.05,
        snowTint: 0xf7faff,
        autoBeam: false
      },
      sunset: {
        sunDir: new THREE.Vector3(-0.88, 0.16, 0.45).normalize(),
        sunColor: 0xffa75e,
        sunIntensity: 3.3,
        hemiSky: 0x627ba8,
        hemiGround: 0x5c4b4e,
        hemiIntensity: 0.68,
        zenith: 0x26447a,
        midSky: 0x8d6e82,
        horizon: 0xf2a572,
        cloudTint: 0xffbfa0,
        fogColor: 0xd99e7e,
        exposure: 1.0,
        snowTint: 0xfff0e4,
        autoBeam: false
      },
      twilight: {
        sunDir: new THREE.Vector3(-0.82, 0.05, -0.55).normalize(),
        sunColor: 0x7898cc,
        sunIntensity: 0.75,
        hemiSky: 0x2c4a78,
        hemiGround: 0x1e2c3e,
        hemiIntensity: 0.58,
        zenith: 0x0b1a36,
        midSky: 0x1e3862,
        horizon: 0x4f6c94,
        cloudTint: 0x657c9e,
        fogColor: 0x374f72,
        exposure: 1.12,
        snowTint: 0xbfd4f0,
        autoBeam: true
      }
    };

    const chkBeam = document.getElementById('chk-beam');
    const chkSnow = document.getElementById('chk-snow');

    function setBeamEnabled(enabled) {
      beamPivot.visible = enabled;
      lampCoreMat.emissiveIntensity = enabled ? 4.8 : 0.45;
      beaconPointLight.intensity = enabled ? 18.0 : 0.0;
      chkBeam.checked = enabled;
    }

    function applyLightPreset(key) {
      const p = LIGHT_PRESETS[key];
      sunLight.position.copy(p.sunDir).multiplyScalar(95);
      sunLight.color.setHex(p.sunColor);
      sunLight.intensity = p.sunIntensity;

      hemiLight.color.setHex(p.hemiSky);
      hemiLight.groundColor.setHex(p.hemiGround);
      hemiLight.intensity = p.hemiIntensity;

      skyUniforms.uSunDir.value.copy(p.sunDir);
      skyUniforms.uZenithColor.value.setHex(p.zenith);
      skyUniforms.uMidSkyColor.value.setHex(p.midSky);
      skyUniforms.uHorizonColor.value.setHex(p.horizon);
      skyUniforms.uSunColor.value.setHex(p.sunColor);
      skyUniforms.uCloudTint.value.setHex(p.cloudTint);

      oceanUniforms.uSunColor.value.setHex(p.sunColor);
      terrainUniforms.uSnowTint.value.setHex(p.snowTint);

      scene.fog.color.setHex(p.fogColor);
      renderer.toneMappingExposure = p.exposure;
      setBeamEnabled(p.autoBeam);
      updateEnvironment();
    }

    applyLightPreset('noon');

    // =========================================================================
    // 15. SMOOTH CAMERA TRANSITIONS & UI HANDLERS
    // =========================================================================
    let camTransition = null;
    function goToPreset(key) {
      const targetPreset = CAM_PRESETS[key];
      if (!targetPreset) return;
      camTransition = {
        startPos: camera.position.clone(),
        endPos: targetPreset.pos.clone(),
        startTarget: controls.target.clone(),
        endTarget: targetPreset.target.clone(),
        progress: 0
      };
    }

    document.querySelectorAll('[data-cam]').forEach((btn) => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('[data-cam]').forEach((b) => b.classList.remove('active'));
        btn.classList.add('active');
        goToPreset(btn.dataset.cam);
      });
    });

    document.querySelectorAll('[data-light]').forEach((btn) => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('[data-light]').forEach((b) => b.classList.remove('active'));
        btn.classList.add('active');
        applyLightPreset(btn.dataset.light);
      });
    });

    chkBeam.addEventListener('change', (e) => setBeamEnabled(e.target.checked));
    chkSnow.addEventListener('change', (e) => { snowPoints.visible = e.target.checked; });

    // Cancel camera transition if user manually grabs controls
    controls.addEventListener('start', () => { camTransition = null; });

    const hudEl = document.getElementById('hud');
    const toggleHudBtn = document.getElementById('toggle-hud');
    toggleHudBtn.addEventListener('click', () => {
      hudEl.classList.toggle('collapsed');
      toggleHudBtn.textContent = hudEl.classList.contains('collapsed') ? '+' : '−';
    });

    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // =========================================================================
    // 16. RENDER LOOP
    // =========================================================================
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const dt = Math.min(clock.getDelta(), 0.05);
      const elapsed = clock.getElapsedTime();

      oceanUniforms.uTime.value = elapsed;
      skyUniforms.uTime.value = elapsed;
      terrainUniforms.uTime.value = elapsed;

      if (beamPivot.visible) {
        beamPivot.rotation.y = elapsed * 0.65;
      }

      if (snowPoints.visible) {
        const sp = snowGeo.attributes.position.array;
        for (let i = 0; i < snowCount; i++) {
          sp[i * 3]     += Math.sin(elapsed * 0.7 + snowSeeds[i]) * dt * 0.9 + dt * 0.75;
          sp[i * 3 + 1] -= dt * (1.8 + (i % 5) * 0.25);
          if (sp[i * 3 + 1] < 0.2) {
            sp[i * 3 + 1] = 34.0;
            sp[i * 3] = (Math.random() - 0.5) * 90;
          }
          if (sp[i * 3] > 45) sp[i * 3] = -45;
        }
        snowGeo.attributes.position.needsUpdate = true;
      }

      if (camTransition) {
        camTransition.progress = Math.min(1, camTransition.progress + dt * 1.15);
        const t = camTransition.progress;
        const ease = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
        camera.position.lerpVectors(camTransition.startPos, camTransition.endPos, ease);
        controls.target.lerpVectors(camTransition.startTarget, camTransition.endTarget, ease);
        if (camTransition.progress >= 1) camTransition = null;
      }

      controls.update();
      renderer.render(scene, camera);
    }

    // Hide loading screen once first frame is ready
    renderer.render(scene, camera);
    document.getElementById('loading').classList.add('hidden');
    animate();
  </script>
</body>
</html>
